sc_cat_item_producer.script:
(function() {

    var choice = (producer.what_do_you_want_to_do + '').toLowerCase();


    /*
     * =========================================================
     * CREATE TEAM
     * =========================================================
     */

    if (choice.indexOf('create') > -1) {

        current.team_name = producer.team_name;
        current.event = producer.select_event;
        current.team_lead = gs.getUserID();

        // Formation Type selected by the student
        current.formation_type = producer.formation_type;

        // New teams always start as Open
        current.status = 'open';


        /*
         * Do NOT use current.insert().
         *
         * The Record Producer automatically inserts
         * the Teams record after this script finishes.
         *
         * The Team Lead will be added as the first
         * Team Member through the After Insert Business Rule.
         */


        /*
         * Redirect to Campus Connect Home
         */

        producer.portal_redirect =
            "?id=campus_connect_home";
    }


    /*
     * =========================================================
     * JOIN TEAM
     * =========================================================
     */

    else if (choice.indexOf('join') > -1) {

        var selectedTeam = producer.select_team_to_join;


        /*
         * Validate selected team
         */

        if (!selectedTeam) {

            gs.addErrorMessage(
                'Please select a team to join.'
            );

            return;
        }


        /*
         * Verify selected team exists
         * and is still Open.
         */

        var teamGr = new GlideRecord(
            'x_snc_campus_con_0_teams'
        );


        if (!teamGr.get(selectedTeam)) {

            gs.addErrorMessage(
                'The selected team could not be found.'
            );

            return;
        }


        if (teamGr.getValue('status') != 'open') {

            gs.addErrorMessage(
                'This team is no longer open for joining.'
            );

            return;
        }


        /*
         * Prevent duplicate membership/request
         */

        var existingMember = new GlideRecord(
            'x_snc_campus_con_0_team_members'
        );


        existingMember.addQuery(
            'team',
            selectedTeam
        );


        existingMember.addQuery(
            'student',
            gs.getUserID()
        );


        existingMember.setLimit(1);
        existingMember.query();


        if (existingMember.next()) {

            gs.addErrorMessage(
                'You already have a membership or request for this team.'
            );

            return;
        }


        /*
         * Count accepted members
         */

        var countGr = new GlideAggregate(
            'x_snc_campus_con_0_team_members'
        );


        countGr.addQuery(
            'team',
            selectedTeam
        );


        countGr.addQuery(
            'join_status',
            'Accepted'
        );


        countGr.addAggregate('COUNT');
        countGr.query();


        var acceptedCount = 0;


        if (countGr.next()) {

            acceptedCount = parseInt(
                countGr.getAggregate('COUNT'),
                10
            ) || 0;
        }


        /*
         * Maximum team size = 5
         */

        if (acceptedCount >= 5) {

            teamGr.setValue(
                'status',
                'closed'
            );

            teamGr.update();


            gs.addErrorMessage(
                'This team is already full.'
            );

            return;
        }


        /*
         * Create Team Member request
         */

        var tm = new GlideRecord(
            'x_snc_campus_con_0_team_members'
        );


        tm.initialize();


        tm.setValue(
            'team',
            selectedTeam
        );


        tm.setValue(
            'student',
            gs.getUserID()
        );


        tm.setValue(
            'join_status',
            'Requested'
        );


        tm.setValue(
            'commitment_confirmed',
            true
        );


        var memberId = tm.insert();


        /*
         * Verify insert
         */

        if (!memberId) {

            gs.addErrorMessage(
                'Unable to create the team join request.'
            );

            return;
        }


        /*
         * Success message
         */

        gs.addInfoMessage(
            'Team join request sent successfully.'
        );


        /*
         * Redirect to My Team Requests
         */

        producer.portal_redirect =
            "?id=my_team_requests";
    }

})();
